-- ZUVOORA Engage — Phase 2b: website domain registration and DNS TXT verification (ADR-022).
--
--   * Any clinic may CLAIM a hostname, but only one clinic can hold it VERIFIED at a time
--     (partial unique index). Verification proves DNS control, so squatting a hostname gains
--     nothing and cannot block the real owner.
--   * The verification token is generated by the database and can never be chosen or changed
--     by a client. Hostname and token are immutable after creation.
--   * The API performs the DNS TXT lookup (no HTTP fetches) and is the only writer of the
--     verification result. verified_at / removed_by / created_by are server-set.
--   * Domains are removed (removed_at), never deleted; removed domains are frozen.

alter table public.tenant_domains drop constraint tenant_domains_hostname_key;
alter table public.tenant_domains drop constraint tenant_domains_hostname_check;

alter table public.tenant_domains
  add column verification_token text not null
    default replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
  add column last_checked_at timestamptz,
  add column last_check_result text,
  add column check_count integer not null default 0,
  add column removed_at timestamptz,
  add column removed_by uuid references auth.users (id) on delete set null,
  add column created_by uuid references auth.users (id) on delete set null,
  add column updated_at timestamptz not null default now(),
  add constraint tenant_domains_hostname_format check (
    char_length(hostname) between 4 and 253
    and hostname ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$'
  ),
  add constraint tenant_domains_token_format check (verification_token ~ '^[0-9a-f]{64}$'),
  add constraint tenant_domains_check_result check (
    last_check_result is null
    or last_check_result in ('verified', 'not_found', 'mismatch', 'dns_error', 'timeout')),
  add constraint tenant_domains_check_count check (check_count >= 0),
  add constraint tenant_domains_verified_consistent check (
    (verification_status = 'verified') = (verified_at is not null)),
  add constraint tenant_domains_removed_not_verified check (
    removed_at is null or verification_status <> 'verified');

-- One active claim per tenant per hostname; one verified owner per hostname platform-wide.
create unique index tenant_domains_active_claim_idx
  on public.tenant_domains (tenant_id, hostname) where removed_at is null;
create unique index tenant_domains_verified_hostname_idx
  on public.tenant_domains (hostname) where verification_status = 'verified';

-- ---------------------------------------------------------------------------------------------
-- Integrity triggers
-- ---------------------------------------------------------------------------------------------
create or replace function app_private.domain_before_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.verification_status := 'pending';
  new.verified_at := null;
  new.last_checked_at := null;
  new.last_check_result := null;
  new.check_count := 0;
  new.removed_at := null;
  new.removed_by := null;
  new.created_by := app_private.current_user_id();
  new.created_at := now();
  new.updated_at := now();
  return new;
end;
$$;

create or replace function app_private.domain_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.tenant_id is distinct from old.tenant_id
     or new.hostname is distinct from old.hostname
     or new.verification_token is distinct from old.verification_token then
    raise exception 'domain identity is immutable' using errcode = 'insufficient_privilege';
  end if;
  if old.removed_at is not null then
    raise exception 'removed domains cannot be changed' using errcode = 'check_violation';
  end if;

  if new.removed_at is not null then  -- removal: server-set time/actor; loses verification
    new.removed_at := now();
    new.removed_by := app_private.current_user_id();
    new.verification_status := 'pending';
  end if;

  if new.verification_status = 'verified' and old.verification_status <> 'verified' then
    new.verified_at := now();
  elsif new.verification_status <> 'verified' then
    new.verified_at := null;
  else
    new.verified_at := old.verified_at;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

revoke all on function app_private.domain_before_insert() from public, anon, authenticated;
revoke all on function app_private.domain_before_update() from public, anon, authenticated;

create trigger tenant_domains_insert before insert on public.tenant_domains
  for each row execute function app_private.domain_before_insert();
create trigger tenant_domains_update before update on public.tenant_domains
  for each row execute function app_private.domain_before_update();

-- ---------------------------------------------------------------------------------------------
-- RLS write policies (select policy exists from Phase 1): owners/admins and MFA platform admins.
-- ---------------------------------------------------------------------------------------------
create policy tenant_domains_insert on public.tenant_domains for insert to engage_app
  with check (app_private.is_platform_admin()
    or app_private.has_tenant_role(tenant_id, array['owner', 'admin']::public.membership_role[]));

create policy tenant_domains_update on public.tenant_domains for update to engage_app
  using (app_private.is_platform_admin()
    or app_private.has_tenant_role(tenant_id, array['owner', 'admin']::public.membership_role[]))
  with check (app_private.is_platform_admin()
    or app_private.has_tenant_role(tenant_id, array['owner', 'admin']::public.membership_role[]));

-- Privileges: clients choose only tenant + hostname; everything else is server/trigger-owned.
grant insert (tenant_id, hostname) on public.tenant_domains to engage_app;
grant update (verification_status, last_checked_at, last_check_result, check_count, removed_at)
  on public.tenant_domains to engage_app;
